1	import { useState, useMemo } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  Calculator, Plus, Search, CheckCircle2, Clock, Archive,
5	  ChevronDown, Trash2, Workflow,
6	} from 'lucide-react';
7	import { cn } from '@/shared/lib/utils';
8	import { Badge } from '@/shared/ui/badge';
9	import { Button } from '@/shared/ui/button';
10	import { Input } from '@/shared/ui/input';
11	import {
12	  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
13	} from '@/shared/ui/dialog';
14	import {
15	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
16	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
17	} from '@/shared/ui/alert-dialog';
18	import {
19	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
20	} from '@/shared/ui/select';
21	import {
22	  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
23	  DropdownMenuSeparator, DropdownMenuTrigger,
24	} from '@/shared/ui/dropdown-menu';
25	import { useCmvFichas, type CmvStatus } from '@/features/financeiro/model/useCmvFichas';
26	import { MommaPageLayout } from "@/shared/ui/MommaPageLayout";
27	
28	const STATUS_CONFIG: Record<CmvStatus, { label: string; icon: typeof Clock; className: string }> = {
29	  rascunho: {
30	    label: 'Rascunho',
31	    icon: Clock,
32	    className: 'bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300',
33	  },
34	  aprovada: {
35	    label: 'Aprovada',
36	    icon: CheckCircle2,
37	    className: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400',
38	  },
39	  obsoleta: {
40	    label: 'Obsoleta',
41	    icon: Archive,
42	    className: 'bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
43	  },
44	};
45	
46	const fmt = (n: number | null | undefined): string => {
47	  if (typeof n !== 'number') return 'R$ 0,00';
48	  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
49	};
50	
51	export default function CmvPage() {
52	  const navigate = useNavigate();
53	  const {
54	    cmvList,
55	    availableFichas,
56	    isLoading,
57	    createCmv,
58	    updateCmvStatus,
59	    deleteCmv,
60	  } = useCmvFichas();
61	
62	  const [busca, setBusca] = useState('');
63	  const [statusFiltro, setStatusFiltro] = useState<CmvStatus | 'todos'>('todos');
64	  const [isNewDialogOpen, setIsNewDialogOpen] = useState(false);
65	  const [newCmvNome, setNewCmvNome] = useState('');
66	  const [selectedFichaId, setSelectedFichaId] = useState<string>('');
67	  const [deleteId, setDeleteId] = useState<number | null>(null);
68	
69	  const filteredCmvs = useMemo(() => {
70	    return cmvList.filter((cmv) => {
71	      const matchBusca =
72	        cmv.nome.toLowerCase().includes(busca.toLowerCase()) ||
73	        (cmv.ficha_nome ?? '').toLowerCase().includes(busca.toLowerCase());
74	      const matchStatus = statusFiltro === 'todos' || cmv.status === statusFiltro;
75	      return matchBusca && matchStatus;
76	    });
77	  }, [cmvList, busca, statusFiltro]);
78	
79	  const handleCreate = async () => {
80	    if (!selectedFichaId || !newCmvNome.trim()) return;
81	    const fichaId = Number(selectedFichaId);
82	    if (!Number.isFinite(fichaId)) return;
83	    const result = await createCmv.mutateAsync({ ficha_tecnica_id: fichaId, nome: newCmvNome.trim() });
84	    setIsNewDialogOpen(false);
85	    if (result?.id) {
86	      navigate(`/financeiro/cmv/configurador?focus=${result.id}`);
87	    }
88	  };
89	
90	  const handleDelete = async () => {
91	    if (!deleteId) return;
92	    await deleteCmv.mutateAsync(deleteId);
93	    setDeleteId(null);
94	  };
95	
96	  const handleFichaSelect = (fichaId: string) => {
97	    setSelectedFichaId(fichaId);
98	    if (!newCmvNome) {
99	      const ficha = availableFichas.find((f) => f.id === Number(fichaId));
100	      if (ficha) setNewCmvNome(`CMV — ${ficha.nome}`);
101	    }
102	  };
103	
104	  return (
105	    <MommaPageLayout>
106	      <div className="relative z-10 w-full max-w-[1600px] mx-auto px-4 sm:px-6 py-8 mt-2">
107	        {/* Header */}
108	        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
109	          <div className="flex items-center gap-3">
110	            <div className="rounded-2xl bg-[#57715B]/10 p-3">
111	              <Calculator className="h-6 w-6 text-[#57715B]" />
112	            </div>
113	            <div>
114	              <h1 className="text-2xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
115	                CMV
116	              </h1>
117	              <p className="text-xs uppercase tracking-widest text-muted-foreground">
118	                Custo de Mercadoria Vendida
119	              </p>
120	            </div>
121	          </div>
122	
123	          <Button
124	            className="bg-[#57715B] hover:bg-[#465b49] text-white shadow-lg shadow-[#57715B]/20"
125	            onClick={() => {
126	              setNewCmvNome('');
127	              setSelectedFichaId('');
128	              setIsNewDialogOpen(true);
129	            }}
130	          >
131	            <Plus className="mr-1.5 h-4 w-4" />
132	            Novo CMV
133	          </Button>
134	        </div>
135	
136	        {/* Filtros */}
137	        <div className="flex flex-wrap gap-2 mb-6">
138	          <div className="relative flex-1 min-w-[180px] max-w-xs">
139	            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
140	            <Input
141	              className="pl-8 h-9 text-sm"
142	              placeholder="Buscar CMV ou ficha..."
143	              value={busca}
144	              onChange={(e) => setBusca(e.target.value)}
145	            />
146	          </div>
147	          <Select
148	            value={statusFiltro}
149	            onValueChange={(v) => setStatusFiltro(v as CmvStatus | 'todos')}
150	          >
151	            <SelectTrigger className="h-9 w-[160px] text-sm">
152	              <SelectValue placeholder="Status" />
153	            </SelectTrigger>
154	            <SelectContent>
155	              <SelectItem value="todos">Todos os status</SelectItem>
156	              <SelectItem value="rascunho">Rascunho</SelectItem>
157	              <SelectItem value="aprovada">Aprovada</SelectItem>
158	              <SelectItem value="obsoleta">Obsoleta</SelectItem>
159	            </SelectContent>
160	          </Select>
161	        </div>
162	
163	        {/* Content */}
164	        {isLoading ? (
165	          <div className="flex items-center justify-center py-20 text-muted-foreground text-sm">
166	            Carregando CMVs...
167	          </div>
168	        ) : filteredCmvs.length === 0 ? (
169	          <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
170	            <div className="rounded-2xl bg-[#57715B]/10 p-4">
171	              <Calculator className="h-10 w-10 text-[#57715B]" />
172	            </div>
173	            <p className="text-sm text-muted-foreground">
174	              {cmvList.length === 0
175	                ? 'Nenhum CMV cadastrado. Crie o primeiro!'
176	                : 'Nenhum CMV corresponde aos filtros.'}
177	            </p>
178	            {cmvList.length === 0 && (
179	              <Button
180	                size="sm"
181	                variant="outline"
182	                onClick={() => { setNewCmvNome(''); setSelectedFichaId(''); setIsNewDialogOpen(true); }}
183	              >
184	                <Plus className="mr-1.5 h-4 w-4" />
185	                Criar primeiro CMV
186	              </Button>
187	            )}
188	          </div>
189	        ) : (
190	          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
191	            {filteredCmvs.map((cmv) => {
192	              const st = STATUS_CONFIG[cmv.status];
193	              const Icon = st.icon;
194	              const rendimento = cmv.ficha_rendimento_quantidade ?? 1;
195	              const custoFichaTotal = cmv.ficha_custo_calculado ?? 0;
196	              const unitarioFicha = rendimento > 0 ? custoFichaTotal / rendimento : 0;
197	              const custoTotal = cmv.custo_calculado ?? 0;
198	              const extras = Math.max(0, custoTotal - unitarioFicha);
199	
200	              return (
201	                <div
202	                  key={cmv.id}
203	                  className="group relative rounded-2xl border border-white/30 dark:border-white/10 bg-white/60 dark:bg-zinc-900/40 backdrop-blur-xl shadow-sm hover:shadow-xl hover:-translate-y-1 p-5 transition-all duration-300 overflow-hidden"
204	                >
205	                  <div className="absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-black/5 pointer-events-none" />
206	                  <div className="relative z-10">
207	                    <div className="flex items-start justify-between gap-3 mb-3">
208	                      <div className="flex-1 min-w-0">
209	                        <p className="font-semibold text-base text-foreground truncate">{cmv.nome}</p>
210	                        {cmv.ficha_nome && (
211	                          <p className="text-xs text-muted-foreground truncate mt-0.5 flex items-center gap-1">
212	                            <Workflow className="h-3 w-3 shrink-0" />
213	                            {cmv.ficha_nome}
214	                          </p>
215	                        )}
216	                      </div>
217	
218	                      <DropdownMenu>
219	                        <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
220	                          <Button
221	                            variant="ghost"
222	                            size="icon"
223	                            className="h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity"
224	                          >
225	                            <ChevronDown className="h-4 w-4" />
226	                          </Button>
227	                        </DropdownMenuTrigger>
228	                        <DropdownMenuContent align="end">
229	                          <DropdownMenuItem
230	                            onClick={() => navigate(`/financeiro/cmv/configurador?focus=${cmv.id}`)}
231	                          >
232	                            <Workflow className="mr-2 h-4 w-4 text-[#57715B]" />
233	                            Abrir no Construtor
234	                          </DropdownMenuItem>
235	                          {cmv.status !== 'aprovada' && (
236	                            <DropdownMenuItem
237	                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'aprovada' })}
238	                            >
239	                              <CheckCircle2 className="mr-2 h-4 w-4 text-emerald-500" />
240	                              Aprovar
241	                            </DropdownMenuItem>
242	                          )}
243	                          {cmv.status !== 'obsoleta' && (
244	                            <DropdownMenuItem
245	                              onClick={() => updateCmvStatus.mutate({ id: cmv.id, status: 'obsoleta' })}
246	                            >
247	                              <Archive className="mr-2 h-4 w-4" />
248	                              Marcar obsoleta
249	                            </DropdownMenuItem>
250	                          )}
251	                          <DropdownMenuSeparator />
252	                          <DropdownMenuItem
253	                            className="text-destructive"
254	                            onClick={() => setDeleteId(cmv.id)}
255	                          >
256	                            <Trash2 className="mr-2 h-4 w-4" />
257	                            Excluir
258	                          </DropdownMenuItem>
259	                        </DropdownMenuContent>
260	                      </DropdownMenu>
261	                    </div>
262	
263	                    <span
264	                      className={cn(
265	                        'inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] uppercase tracking-wider font-bold',
266	                        st.className,
267	                      )}
268	                    >
269	                      <Icon className="h-3 w-3" />
270	                      {st.label}
271	                    </span>
272	
273	                    <div className="mt-4 pt-3 border-t border-[#57715B]/10">
274	                      <div className="flex items-end justify-between">
275	                        <div>
276	                          <p className="text-[10px] text-muted-foreground uppercase tracking-wider mb-0.5">
277	                            Custo total
278	                          </p>
279	                          <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">
280	                            {fmt(custoTotal)}
281	                          </p>
282	                        </div>
283	                        <div className="text-right space-y-0.5">
284	                          <p className="text-[10px] text-muted-foreground">
285	                            Produção:{' '}
286	                            <span className="font-semibold text-foreground tabular-nums">
287	                              {fmt(unitarioFicha)}
288	                            </span>
289	                          </p>
290	                          <p className="text-[10px] text-muted-foreground">
291	                            Extras:{' '}
292	                            <span className="font-semibold text-foreground tabular-nums">
293	                              {fmt(extras)}
294	                            </span>
295	                          </p>
296	                        </div>
297	                      </div>
298	                    </div>
299	                  </div>
300	                </div>
301	              );
302	            })}
303	          </div>
304	        )}
305	      </div>
306	
307	      {/* Dialog Novo CMV */}
308	      <Dialog open={isNewDialogOpen} onOpenChange={setIsNewDialogOpen}>
309	        <DialogContent className="max-w-md">
310	          <DialogHeader>
311	            <DialogTitle>Novo CMV</DialogTitle>
312	          </DialogHeader>
313	          <div className="space-y-4 py-2">
314	            <div className="space-y-2">
315	              <p className="text-sm font-medium">Ficha Técnica Base *</p>
316	              {availableFichas.length === 0 ? (
317	                <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-900/20 p-3 text-sm text-amber-700 dark:text-amber-400">
318	                  Todas as fichas aprovadas já possuem CMV cadastrado.
319	                </div>
320	              ) : (
321	                <Select value={selectedFichaId} onValueChange={handleFichaSelect}>
322	                  <SelectTrigger>
323	                    <SelectValue placeholder="Selecione a ficha aprovada..." />
324	                  </SelectTrigger>
325	                  <SelectContent>
326	                    {availableFichas.map((f) => (
327	                      <SelectItem key={f.id} value={String(f.id)}>
328	                        {f.nome} — {f.rendimento_quantidade} {f.rendimento_unidade}
329	                      </SelectItem>
330	                    ))}
331	                  </SelectContent>
332	                </Select>
333	              )}
334	            </div>
335	
336	            <div className="space-y-2">
337	              <p className="text-sm font-medium">Nome do CMV *</p>
338	              <Input
339	                placeholder="Ex: CMV — Bolo de Chocolate"
340	                value={newCmvNome}
341	                onChange={(e) => setNewCmvNome(e.target.value)}
342	              />
343	            </div>
344	          </div>
345	          <DialogFooter>
346	            <Button variant="outline" onClick={() => setIsNewDialogOpen(false)}>
347	              Cancelar
348	            </Button>
349	            <Button
350	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
351	              onClick={handleCreate}
352	              disabled={
353	                !selectedFichaId ||
354	                !newCmvNome.trim() ||
355	                availableFichas.length === 0 ||
356	                createCmv.isPending
357	              }
358	            >
359	              {createCmv.isPending ? 'Salvando...' : 'Salvar e Abrir Construtor'}
360	            </Button>
361	          </DialogFooter>
362	        </DialogContent>
363	      </Dialog>
364	
365	      {/* Alert delete */}
366	      <AlertDialog open={!!deleteId} onOpenChange={(o) => !o && setDeleteId(null)}>
367	        <AlertDialogContent>
368	          <AlertDialogHeader>
369	            <AlertDialogTitle>Excluir CMV?</AlertDialogTitle>
370	            <AlertDialogDescription>
371	              Esta ação é irreversível. Todos os itens de custo extras e posições do canvas serão removidos.
372	            </AlertDialogDescription>
373	          </AlertDialogHeader>
374	          <AlertDialogFooter>
375	            <AlertDialogCancel>Cancelar</AlertDialogCancel>
376	            <AlertDialogAction
377	              onClick={handleDelete}
378	              className="bg-destructive text-destructive-foreground"
379	            >
380	              Excluir
381	            </AlertDialogAction>
382	          </AlertDialogFooter>
383	        </AlertDialogContent>
384	      </AlertDialog>
385	    </MommaPageLayout>
386	  );
387	}
