1	import { memo, useCallback, useEffect, useState } from 'react';
2	import { useQueryClient } from '@tanstack/react-query';
3	import {
4	  ReactFlow,
5	  ReactFlowProvider,
6	  Background,
7	  BackgroundVariant,
8	  MiniMap,
9	  Panel,
10	  useNodesState,
11	  useEdgesState,
12	  useReactFlow,
13	  Handle,
14	  Position,
15	  type Node,
16	  type Edge,
17	  type NodeTypes,
18	  type NodeDragHandler,
19	  type NodeProps,
20	} from '@xyflow/react';
21	import '@xyflow/react/dist/style.css';
22	import { useNavigate, useSearchParams } from 'react-router-dom';
23	import { supabase } from '@/integrations/supabase/client';
24	import {
25	  useCmvGraph,
26	  cmvNodeId,
27	  fichaNodeId,
28	  insumoNodeId,
29	  type RawCmvItem,
30	} from '@/features/financeiro/model/useCmvGraph';
31	import { layoutGraph } from '@/components/producao/configurador/layout';
32	import { toast } from 'sonner';
33	import {
34	  ArrowLeft,
35	  LayoutTemplate,
36	  Plus,
37	  Save,
38	  Trash2,
39	  Package,
40	  DollarSign,
41	  Loader2,
42	  Calculator,
43	  ChefHat,
44	  Wheat,
45	  Receipt,
46	} from 'lucide-react';
47	import { Button } from '@/shared/ui/button';
48	import { Input } from '@/shared/ui/input';
49	import { Label } from '@/shared/ui/label';
50	import {
51	  Sheet,
