573	  if (loading) {
574	    return (
575	      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex items-center justify-center">
576	        <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
577	      </div>
578	    );
579	  }
580	
581	  if (!cmv) {
582	    return (
583	      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center text-muted-foreground">
584	        <p className="text-sm mb-4">CMV não encontrado.</p>
585	        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
586	          <ArrowLeft className="mr-2 h-4 w-4" />
587	          Voltar
588	        </Button>
589	      </div>
