251	  const formatNcm = (n: string | null) => {
252	    if (!n) return "";
253	    const s = String(n).replace(/[^0-9]/g, "");
254	    if (s.length === 8) return `${s.slice(0,4)}.${s.slice(4,6)}.${s.slice(6,8)}`;
255	    return n;
256	  };
