258	  const formatCurrency = (v: number | null) => {
259	    if (v == null) return "";
260	    try {
261	      return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
262	    } catch {
263	      return String(v);
264	    }
265	  };
266	
267	  const parseCurrency = (s: string) => {
268	    const t = s.trim();
269	    if (!t) return null;
270	    const v = t.replace(/[^0-9,.-]/g, "").replace(/\./g, "").replace(/,/g, ".");
271	    const n = Number(v);
272	    return Number.isFinite(n) ? n : null;
273	  };
